const dlShare = (n, d) => {
  const q = Math.floor(n / d);
  return { q, r: n - q * d };
};
const dlUnits = (c) => Math.floor(c / 10) * 10.5 + c % 10;
const dlFrames = (q) => {
  const out = [];
  for (let f = 10; f <= q; f += 10) out.push(f);
  for (let f = Math.floor(q / 10) * 10 + 1; f <= q; f++) out.push(f);
  return out;
};
const dlRange = (a, b) => {
  const out = [];
  for (let k = a; k <= b; k++) out.push(k);
  return out;
};
const dlNums = (v) => Array.isArray(v) ? v.map(Number) : (String(v != null ? v : "").match(/\d+/g) || []).map(Number);
const dlAdd = (pen, v, hide) => {
  const i = pen.findIndex((c) => c.v === v);
  if (i >= 0) return pen.map((c, j) => j === i ? { ...c, twins: c.twins + 1, hidTw: c.hidTw + (hide ? 1 : 0) } : c);
  return [...pen, { v, twins: 0, hid: hide, hidTw: 0 }].sort((a, b) => a.v - b.v);
};
