            {[13, 20, 27].map((dy) => <line key={dy} x1={gx + 9} y1={R.y(0) - 19 + dy} x2={gx + 25} y2={R.y(0) - 19 + dy} stroke={DL_BLUE} strokeWidth={2.5} strokeLinecap="round" />)}
